import{d as r,C as l,o as s,c as o,j as a,a as i,E as d,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"荀子·第3篇·不苟","description":"《荀子·不苟》——辨别君子的持守与苟且取容。","frontmatter":{"title":"荀子·第3篇·不苟","description":"《荀子·不苟》——辨别君子的持守与苟且取容。","category":"guide","aliases":["荀子不苟","荀子第3篇"],"source":["维基文库《荀子/不苟篇》，修订号 380303"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/xunzi/chapter-03.md","filePath":"lizhimingde/xunzi/chapter-03.md","lastUpdated":1794362429000}'),p={name:"lizhimingde/xunzi/chapter-03.md"},x=r({...p,setup(c){const t=[{id:"p001",sentences:[["君子行不贵苟难，说不贵苟察，名不贵苟传，唯其当之为贵。故怀负石而投河，是行之难为者也，而申徒狄能之；然而君子不贵者，非礼义之中也。山渊平，天地比，齐、秦袭，入乎耳，出乎口，钩有须，卵有毛，是说之难持者也，而惠施、邓析能之；然而君子不贵者，非礼义之中也。盗跖贪凶，名声若日月，与舜、禹俱传而不息；然而君子不贵者，非礼义之中也。故曰：君子行不贵苟难，说不贵苟察，名不贵苟传，唯其当之为贵。《诗》曰：“物其有矣，唯其时矣。”此之谓也。"]]},{id:"p002",sentences:[["君子易知而难狎，易惧而难胁，畏患而不避义死，欲利而不为所非，交亲而不比，言辩而不辞。荡荡乎，其有以殊于世也。"]]},{id:"p003",sentences:[["君子能亦好，不能亦好；小人能亦丑，不能亦丑。君子能则宽容易直以开道人，不能则恭敬繜绌以畏事人；小人能则倨傲僻违以骄溢人，不能则妒嫉怨诽以倾覆人。故曰：君子能则人荣学焉，不能则人乐告之；小人能则人贱学焉，不能则人羞告之。是君子小人之分也。"]]},{id:"p004",sentences:[["君子宽而不僈，廉而不刿，辩而不争，察而不激， 直立而不胜，坚彊而不曓，柔从而不流，恭敬谨慎而容，夫是之谓至文。《诗》曰：“温温恭人，惟德之基。”此之谓也。"]]},{id:"p005",sentences:[["君子崇人之德，扬人之美，非谄谀也；正义直指，举人之过，非毁疵也；言己之光美，拟于舜、禹，参于天地，非夸诞也；与时屈伸，柔从若蒲苇，非慑怯也；刚强猛毅，靡所不信，非骄曓也。以义变应，知当曲直故也。《诗》曰：“左之左之，君子宜之；右之右之，君子有之。”此言君子以义屈信变应故也。"]]},{id:"p006",sentences:[["君子，小人之反也。君子大心则敬天而道，小心则畏义而节；知则明通而类，愚则端悫而法；见由则恭而止，见闭则敬而齐；喜则和而理，忧则静而理；通则文而明，穷则约而详。小人则不然：大心则慢而曓，小心则淫而倾，知则攫盗而渐，愚则毒贼而乱；见由则兑而倨，见闭则怨而险；喜则轻而翾，忧则挫而慑；通则骄而偏，穷则弃而儑。传曰：“君子两进，小人两废。”此之谓也。"]]},{id:"p007",sentences:[["君子治治，非治乱也。曷谓邪？曰：礼义之谓治，非礼义之谓乱也。故君子者，治礼义者也，非治非礼义者也。然则国乱将弗治与？曰：国乱而治之者，非案乱而治之之谓也，去乱而被之以治；人污而修之者，非案污而修之之谓也，去污而易之以修。故去乱而非治乱也，去污而非修污也。治之为名，犹曰君子为治而不为乱，为修而不为污也。"]]},{id:"p008",sentences:[["君子絜其辩而同焉者合矣，善其言而类焉者应矣。故马鸣而马应之，非知也，其埶然也。故新浴者振其衣，新沐者弹其冠，人之情也。其谁能以己之潐潐，受人之掝掝者哉！"]]},{id:"p009",sentences:[["君子养心莫善于诚，致诚则无它事矣，唯仁之为守，唯义之为行。诚心守仁则形，形则神，神则能化矣；诚心行义则理，理则明，明则能变矣。变化代兴，谓之天德。天不言而人推高焉，地不言而人推厚焉，四时不言而百姓期焉。夫此有常，以至其诚者也。君子至德，嘿然而喻，未施而亲，不怒而威。夫此顺命，以慎其独者也。善之为道者，不诚则不独，不独则不形，不形则虽作于心，见于色，出于言，民犹若未从也，虽从必疑。天地为大矣，不诚则不能化万物；圣人为知矣，不诚则不能化万民；父子为亲矣，不诚则疏；君上为尊矣，不诚则卑。夫诚者，君子之所守也，而政事之本也。唯所居以其类至，操之则得之，舍之则失之。操而得之则轻，轻则独行，独行而不舍则济矣。济而材尽，长迁而不反其初则化矣。"]]},{id:"p010",sentences:[["君子位尊而志恭，心小而道大，所听视者近而所闻见者远。是何邪？则操术然也。故千人万人之情，一人之情是也；天地始者，今日是也；百王之道，后王是也。君子审后王之道而论百王之前，若端拜而议。推礼义之统，分是非之分，总天下之要，治海内之众，若使一人，故操弥约而事弥大。五寸之矩，尽天下之方也。故君子不下室堂而海内之情举积此者，则操术然也。"]]},{id:"p011",sentences:[["有通士者，有公士者，有直士者，有悫士者，有小人者。上则能尊君，下则能爱民，物至而应，事起而辨，若是则可谓通士矣。不下比以暗上，不上同以疾下，分争于中，不以私害之，若是，则可谓公士矣。身之所长，上虽不知，不以悖君，身之所短，上虽不知，不以取赏，长短不饰，以情自竭，若是，则可谓直士矣。庸言必信之，庸行必慎之，畏法流俗而不敢以其所独甚，若是，则可谓悫士矣。言无常信，行无常贞，唯利所在，无所不倾，若是，则可谓小人矣。"]]},{id:"p012",sentences:[["公生明，偏生暗，端悫生通，诈伪生塞，诚信生神，夸诞生惑。此六生者，君子慎之，而禹、桀所以分也。"]]},{id:"p013",sentences:[["欲恶取舍之权：见其可欲也，则必前后虑其可恶也者；见其可利也，则必前后虑其可害也者；而兼权之，孰计之，然后定其欲恶取舍。如是，则常不失陷矣。凡人之患，偏伤之也。见其可欲也，则不虑其可恶也者；见其可利也，则不虑其可害也者。是以动则必陷，为则必辱，是偏伤之患也。"]]},{id:"p014",sentences:[["人之所恶者，吾亦恶之。夫富贵者则类傲之，夫贫贱者则求柔之，是非仁人之情也，是奸人将以盗名于晻世者也，险莫大焉。故曰：盗名不如盗货。田仲、史䲡不如盗也。"]]}];return(u,e)=>{const n=l("DaoTextReading");return s(),o("div",null,[e[0]||(e[0]=a("h1",{id:"荀子·第3篇·不苟",tabindex:"-1"},[i("荀子·第3篇·不苟 "),a("a",{class:"header-anchor",href:"#荀子·第3篇·不苟","aria-label":'Permalink to "荀子·第3篇·不苟"'},"​")],-1)),e[1]||(e[1]=a("p",null,"本篇讨论：辨别君子的持守与苟且取容。",-1)),e[2]||(e[2]=a("blockquote",null,[a("p",null,"原文已录入；段级白话、字词点查与三问解读待逐篇补充。原文录入不等于解读完成。")],-1)),e[3]||(e[3]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),e[4]||(e[4]=a("p",null,"经典阅读保留段落；切换「竹简」可连续通读。此阶段按来源自然段呈现，不为未整理的段落预填释义。",-1)),d(n,{sections:t,"default-mode":"classic",tone:"ink",colophon:"荀子 · 不苟","aria-label":"荀子·不苟原文"}),e[5]||(e[5]=h("",8))])}}});export{f as __pageData,x as default};
